<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfilePhoneNumberAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfilePhoneNumberAccessor trait.
 *
 * Covers null default, string/VO assignment via withPhoneNumber,
 * getPhoneNumber/phoneNumber accessors, and isPhoneNumberChanged with/without original.
 */
class UserProfilePhoneNumberAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withPhoneNumber creates a new instance with the PhoneNumber set
     * from a string value, and getPhoneNumber returns the primitive string.
     */
    public function testWithPhoneNumberFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePhoneNumberAccessorUnitTest();

        // Act
        $result = $holder->withPhoneNumber('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getPhoneNumber());
    }
    /**
     * Asserts that withphoneNumber has access to the value object
     * from a string value, and getPhoneNumber returns the primitive string.
     */
    public function testWithPhoneNumberFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePhoneNumberAccessorUnitTest();

        // Act
        $result = $holder->withPhoneNumber('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->phoneNumber()->value());
    }
    public function testChangedPhoneNumber(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePhoneNumberAccessorUnitTest();
        $original = $holder->withPhoneNumber('one');
        $same = $holder->withPhoneNumber('one');
        $modified = $holder->withPhoneNumber('other');

        // Act
        $unchanged = $holder->isPhoneNumberChanged();
        $withSame = $original->isPhoneNumberChanged($same);
        $withDiferent = $original->isPhoneNumberChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfilePhoneNumberAccessorUnitTest
{
    use UserProfilePhoneNumberAccessor;
}
